    .font({ family: 'serif', style: 'italic', size: 15, anchor: 'middle' })
    .attr('paint-order', 'stroke').stroke({ color: '#fff', width: 3 })
    .center(plotX(0.4), yTop - 11);
  var Lpx = Math.max(9, Math.min(frame.width, frame.height) * 0.026);
  for (var gx = -2.3; gx <= 3.15; gx += 0.42) {
    for (var gy = -0.7; gy <= 4.75; gy += 0.5) {
      var dxm = Math.cos(gx), dym = Math.sin(gx);
      var cx = plotX(gx), cy = plotY(gy);
      var hx = dxm * Lpx / 2, hy = -dym * Lpx / 2;
      drawArrow(gField, cx - hx, cy - hy, cx + hx, cy + hy, '#222', 1.1, 4.2);
    }
  }
  gField.css('cursor', 'pointer');
  gField.on('mousemove', function (e) { showTooltip('F(x, y) = cos(x) i + sin(x) j — direction depends only on x', e); });
  gField.on('mouseleave', function () { hideTooltip(); });
  gField.on('click', function () {
    showPopup('The vector field', 'F(x, y) = (cos x, sin x) depends only on x: arrows point straight down near x = −π/2, rightward near x = 0, up near x = π/2, and left near x = ±π. Both panels integrate this SAME field — only the path C changes.');
  });
}

function drawAxes() {
  gAxes.clear();
  var axY = plotY(0), axX = plotX(0);
  drawArrow(gAxes, plotX(frame.xDomain[0]) + 2, axY, plotX(frame.xDomain[1]) - 3, axY, '#000', 1.5, 9);
  drawArrow(gAxes, axX, plotY(frame.yDomain[0]) + 2, axX, plotY(frame.yDomain[1]) - 3, '#000', 1.5, 9);
  gAxes.text('x').font({ family: 'serif', style: 'italic', size: 15 }).move(plotX(frame.xDomain[1]) - 15, axY - 20);
  gAxes.text('y').font({ family: 'serif', style: 'italic', size: 15 }).move(axX + 9, plotY(frame.yDomain[1]) + 2);

  var xticks, yticks, i;
  if (state.panel === 'A') {
    xticks = [{ v: -Math.PI / 2, l: '−π/2' }];
    yticks = [{ v: 1, l: '1' }, { v: 2, l: '2' }];
  } else {
    xticks = [{ v: -2, l: '−2' }, { v: -1, l: '−1' }, { v: 1, l: '1' }, { v: 2, l: '2' }, { v: 3, l: '3' }];
    yticks = [{ v: 1, l: '1' }, { v: 2, l: '2' }, { v: 3, l: '3' }, { v: 4, l: '4' }];
  }
  for (i = 0; i < xticks.length; i++) {
    var tx = plotX(xticks[i].v);
    gAxes.line(tx, axY - 4, tx, axY + 4).stroke({ color: '#000', width: 1.2 });
    gAxes.text(xticks[i].l).font({ family: 'serif', style: 'italic', size: 13, anchor: 'middle' })
      .attr('paint-order', 'stroke').stroke({ color: '#fff', width: 3 }).move(tx, axY + 7);
  }
  for (i = 0; i < yticks.length; i++) {
    var ty = plotY(yticks[i].v);
    gAxes.line(axX - 4, ty, axX + 4, ty).stroke({ color: '#000', width: 1.2 });
    gAxes.text(yticks[i].l).font({ family: 'serif', style: 'italic', size: 13, anchor: 'end' })
      .attr('paint-order', 'stroke').stroke({ color: '#fff', width: 3 }).move(axX - 7, ty - 8);
  }
  gAxes.text(state.panel === 'A' ? '(a)' : '(b)')
    .font({ family: 'serif', style: 'italic', size: 15, anchor: 'middle' })
    .center(plotX(0.4), plotY(-1.04));
}

function endpoints() {
  if (state.panel === 'A') return [{ x: seg.p0.x, y: seg.p0.y }, { x: seg.p1.x, y: seg.p1.y }];
  return [{ x: par.p0.x, y: par.p0.x * par.p0.x }, { x: par.p1.x, y: par.p1.x * par.p1.x }];
}

function curveArrowhead(t) {
  var px = fx(t), py = fy(t), v = fv(t), n = Math.hypot(v.x, v.y);
  if (n < 1e-9) return;
  var ux = v.x / n, uy = v.y / n;
  var tip = [plotX(px + ux * 0.10), plotY(py + uy * 0.10)];
  var b1 = [plotX(px - ux * 0.03 - uy * 0.055), plotY(py - uy * 0.03 + ux * 0.055)];
  var b2 = [plotX(px - ux * 0.03 + uy * 0.055), plotY(py - uy * 0.03 - ux * 0.055)];
  gAnno.polygon(tip.join(',') + ' ' + b1.join(',') + ' ' + b2.join(',')).fill('#d42b2b').stroke('none');
}

function updateAnnotations() {
  gAnno.clear();
  if (state.panel === 'B') {
    var pts = [];
    for (var gx = -2.25; gx <= 2.25; gx += 0.15) pts.push([plotX(gx), plotY(gx * gx)]);
    gAnno.polyline(pts.map(function (p) { return p.join(','); }).join(' '))
      .fill('none').stroke({ color: '#c5c5c5', width: 1, dasharray: '4,4' });
  }
  var ts = state.panel === 'A' ? [0.55] : [0.18, 0.62];
  for (var i = 0; i < ts.length; i++) curveArrowhead(ts[i]);
  var ep = endpoints();
  d0.center(plotX(ep[0].x), plotY(ep[0].y));
  d1.center(plotX(ep[1].x), plotY(ep[1].y));
}

function updateMarker() {
  gMarker.clear();
  var t = state.t, x = fx(t), y = fy(t);
  var v = fv(t), n = Math.hypot(v.x, v.y);
  if (n > 1e-9) drawArrowWorld(gMarker, x, y, x + (v.x / n) * 0.45, y + (v.y / n) * 0.45, '#1565c0', 2, 7);
  drawArrowWorld(gMarker, x, y, x + Math.cos(x) * 0.45, y + Math.sin(x) * 0.45, '#1a7f37', 2, 7);
  gMarker.circle(8).center(plotX(x), plotY(y)).fill('#222').stroke({ color: '#fff', width: 1.5 });
}

function updateReadouts() {
  var total = integrateSimpson(integrand, 0, 1, 400);
  document.getElementById('intTotal').textContent = '∫C F·dr ≈ ' + total.toFixed(3);
  var t = state.t, v = fv(t), n = Math.hypot(v.x, v.y);
  var fdotT = n > 1e-9 ? integrand(t) / n : 0;
  var run = t > 1e-4 ? integrateSimpson(integrand, 0, t, 200) : 0;
  document.getElementById('intLocal').innerHTML =
    't = ' + t.toFixed(2) + ' · F·T = <b style="color:' + (fdotT >= 0 ? '#1a7f37' : '#c00000') + '">' +
    fdotT.toFixed(2) + '</b> · ∫₀ᵗ F·dr ≈ ' + run.toFixed(2);
}

function refresh() {
  curve.sample();
  updateAnnotations();
  updateMarker();
  updateReadouts();
}

function setPanel(p) {
  state.panel = p;
  document.getElementById('panelSelectInput').classList.toggle('active', p === 'A');
  document.getElementById('panelSelectBInput').classList.toggle('active', p === 'B');
  drawAxes();
  refresh();
}

function update_paramT(v) {
  state.t = v;
  updateMarker();
  updateReadouts();
}

/* ── Endpoint dragging ─────────────────────────────────────────────────── */
var dragIdx = -1;
d0.on('pointerdown', function (e) { dragIdx = 0; e.preventDefault(); e.stopPropagation(); });
d1.on('pointerdown', function (e) { dragIdx = 1; e.preventDefault(); e.stopPropagation(); });
window.addEventListener('pointermove', function (e) {
  if (dragIdx < 0) return;
  var rect = draw.node.getBoundingClientRect();
  var px = e.clientX - rect.left, py = e.clientY - rect.top;
  var wx = frame.xDomain[0] + (px - frame.margin) / frame.sx;
  var wy = frame.yDomain[0] + (frame.height - frame.margin - py) / frame.sy;
  if (state.panel === 'A') {
    var p = dragIdx === 0 ? seg.p0 : seg.p1;
    p.x = clamp(wx, -2.4, 3.15); p.y = clamp(wy, -0.9, 4.75);
  } else {
    var q = dragIdx === 0 ? par.p0 : par.p1;
    q.x = clamp(wx, -2.2, 2.2);
  }
  refresh();
});
window.addEventListener('pointerup', function () { dragIdx = -1; });

/* ── Curve hover / click ───────────────────────────────────────────────── */
curve.node.css('cursor', 'pointer');
curve.node.on('mousemove', function (e) { showTooltip('Path C — click for explanation', e); });
curve.node.on('mouseleave', function () { hideTooltip(); });
curve.node.on('click', function () {
  showPopup('Line integral ∫C F·dr', 'The integral accumulates F·dr = (F·T) ds along the whole oriented curve. Where the field points along the motion the contribution is positive; where it opposes the motion it is negative; where it is perpendicular it contributes nothing. Sweep t to see each local contribution, and drag the endpoints to feel how the value depends on the path, not just its endpoints.');
});

/* ── Demo steps ────────────────────────────────────────────────────────── */
var steps = [
  { title: 'Step 1 — Panel (a): a path aligned with the field', panel: 'A', t: 0.5,
    narration: 'At x = −π/2 the field is F = (cos x, sin x) = (0, −1): it points straight down, and C is directed downward too. The green field arrow and blue tangent arrow coincide, so F·T = +1 all along and the integral is a small positive number.' },
  { title: 'Step 2 — Reshape the segment', panel: 'A', t: 0,
    narration: 'Now drag the red endpoints of C. As the segment tilts away from the field direction, F·T shrinks (and can even change sign along the path) — the integral updates live, showing it measures alignment with the field, not just the displacement between endpoints.' },
  { title: 'Step 3 — Panel (b): a long curved path', panel: 'B', t: 0.7,
    narration: 'The arc descends from (−1, 1) through the origin and climbs to (2, 4). Sweep t: on the descent the field partly opposes the motion, but the long rightward climb near x = 0 aligns with the rightward-pointing field, adding large positive contributions.' },
  { title: 'Step 4 — Compare the two integrals', panel: 'B', t: 1,
    narration: 'Toggle between the panels: the short segment in (a) accumulates a small single-signed value (≈ 1), while the long arc in (b) traverses far more of the field and ends with a much larger accumulation. Same field — the path decides the integral.' }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = i;
  var s = steps[i];
  setPanel(s.panel);
  var sl = document.getElementById('paramTInput');
  sl.value = s.t;
  document.getElementById('paramTVal').value = s.t.toFixed(2);
  update_paramT(s.t);
  document.getElementById('demoNarration').textContent = s.title + ': ' + s.narration;
  document.getElementById('stepLabel').textContent = (i + 1) + ' / ' + steps.length;
}
function nextStep() { applyStep(Math.min(steps.length - 1, stepIdx + 1)); }
function prevStep() { applyStep(Math.max(0, stepIdx - 1)); }

/* ── Resize: plots resample via setPlotFrame; custom art redrawn here ──── */
document.addEventListener('fig-resize', function () {
  drawField();
  drawAxes();
  updateAnnotations();
  updateMarker();
});

/* ── Initial render ────────────────────────────────────────────────────── */
drawField();
drawAxes();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: The line integral of a vector field along an oriented curve accumulates the field's tangential component along the path, so its value depends on the curve's shape, length, and direction relative to the field — not just its endpoints.
KEY INSIGHT (what students should walk away understanding): A line integral ∫C F·dr accumulates the signed tangential component of F along the whole path, so it depends on the curve's geometry and orientation relative to the field — two paths between similar regions of the same field can give very different values.
DEMO STEPS: 4 guided steps — implement the step player in #ui

FULL BLUEPRINT:
