  if (n > 1e-9) drawArrowWorld(gMarker, x, y, x + (v.x / n) * 0.45, y + (v.y / n) * 0.45, '#1565c0', 2, 7);
  drawArrowWorld(gMarker, x, y, x + Math.cos(x) * 0.45, y + Math.sin(x) * 0.45, '#1a7f37', 2, 7);
  gMarker.circle(8).center(plotX(x), plotY(y)).fill('#222').stroke({ color: '#fff', width: 1.5 });
}

function updateReadouts() {
  var total = integrateSimpson(integrand, 0, 1, 400);
  document.getElementById('intTotal').textContent = '∫C F·dr ≈ ' + total.toFixed(3);
  var t = state.t, v = fv(t), n = Math.hypot(v.x, v.y);
  var fdotT = n > 1e-9 ? integrand(t) / n : 0;
  var run = t > 1e-4 ? integrateSimpson(integrand, 0, t, 200) : 0;
  document.getElementById('intLocal').innerHTML =
    't = ' + t.toFixed(2) + ' · F·T = <b style="color:' + (fdotT >= 0 ? '#1a7f37' : '#c00000') + '">' +
    fdotT.toFixed(2) + '</b> · ∫₀ᵗ F·dr ≈ ' + run.toFixed(2);
}

function refresh() {
  curve.sample();
  updateAnnotations();
  updateMarker();
  updateReadouts();
}

function setPanel(p) {
  state.panel = p;
  document.getElementById('panelSelectInput').classList.toggle('active', p === 'A');
  document.getElementById('panelSelectBInput').classList.toggle('active', p === 'B');
  drawAxes();
  refresh();
}

function update_paramT(v) {
  state.t = v;
  updateMarker();
  updateReadouts();
}

/* ── Endpoint dragging ─────────────────────────────────────────────────── */
var dragIdx = -1;
d0.on('pointerdown', function (e) { dragIdx = 0; e.preventDefault(); e.stopPropagation(); });
d1.on('pointerdown', function (e) { dragIdx = 1; e.preventDefault(); e.stopPropagation(); });
window.addEventListener('pointermove', function (e) {
  if (dragIdx < 0) return;
  var rect = draw.node.getBoundingClientRect();
  var px = e.clientX - rect.left, py = e.clientY - rect.top;
  var wx = frame.xDomain[0] + (px - frame.margin) / frame.sx;
  var wy = frame.yDomain[0] + (frame.height - frame.margin - py) / frame.sy;
  if (state.panel === 'A') {
    var p = dragIdx === 0 ? seg.p0 : seg.p1;
    p.x = clamp(wx, -2.4, 3.15); p.y = clamp(wy, -0.9, 4.75);
  } else {
    var q = dragIdx === 0 ? par.p0 : par.p1;
    q.x = clamp(wx, -2.2, 2.2);
  }
  refresh();
});
window.addEventListener('pointerup', function () { dragIdx = -1; });

/* ── Curve hover / click ───────────────────────────────────────────────── */
curve.node.css('cursor', 'pointer');
curve.node.on('mousemove', function (e) { showTooltip('Path C — click for explanation', e); });
curve.node.on('mouseleave', function () { hideTooltip(); });
curve.node.on('click', function () {
  showPopup('Line integral ∫C F·dr', 'The integral accumulates F·dr = (F·T) ds along the whole oriented curve. Where the field points along the motion the contribution is positive; where it opposes the motion it is negative; where it is perpendicular it contributes nothing. Sweep t to see each local contribution, and drag the endpoints to feel how the value depends on the path, not just its endpoints.');
});

/* ── Demo steps ────────────────────────────────────────────────────────── */
var steps = [
  { title: 'Step 1 — Panel (a): a path against the field', panel: 'A', t: 0.5,
    narration: 'At x = −π/2 the field is F = (cos x, sin x) = (0, −1): it points straight down, but C is directed upward from (−π/2, 1) to (−π/2, 2). The green field arrow and blue tangent arrow oppose each other, so F·T = −1 all along and the integral accumulates to ≈ −1.' },
  { title: 'Step 2 — Reshape the segment', panel: 'A', t: 0,
    narration: 'Now drag the red endpoints of C. As the segment tilts away from straight-up, the dot product F·T grows less negative (and can even change sign along the path) — the integral updates live, showing it measures alignment with the field, not just the displacement between endpoints.' },
  { title: 'Step 3 — Panel (b): a long curved path', panel: 'B', t: 0.7,
    narration: 'The arc descends from (−1, 1) through the origin and climbs to (2, 4). Sweep t: on the descent the field partly opposes the motion, but the long rightward climb near x = 0 aligns with the rightward-pointing field, adding large positive contributions.' },
  { title: 'Step 4 — Compare the two integrals', panel: 'B', t: 1,
    narration: 'Toggle between the panels: the short segment in (a) accumulates a small single-signed value (≈ −1, since the field opposes the motion), while the long arc in (b) traverses far more of the field and ends with a much larger accumulation. Same field — the path decides the integral.' }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = i;
  var s = steps[i];
  setPanel(s.panel);
  var sl = document.getElementById('paramTInput');
  sl.value = s.t;
  document.getElementById('paramTVal').value = s.t.toFixed(2);
  update_paramT(s.t);
  document.getElementById('demoNarration').textContent = s.title + ': ' + s.narration;
  document.getElementById('stepLabel').textContent = (i + 1) + ' / ' + steps.length;
}
function nextStep() { applyStep(Math.min(steps.length - 1, stepIdx + 1)); }
function prevStep() { applyStep(Math.max(0, stepIdx - 1)); }

/* ── Resize: plots resample via setPlotFrame; custom art redrawn here ──── */
document.addEventListener('fig-resize', function () {
  drawField();
  drawAxes();
  updateAnnotations();
  updateMarker();
});

/* ── Initial render ────────────────────────────────────────────────────── */
drawField();
drawAxes();
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

